{
  "name": "可编程量子系统控制器",
  "name_en": "Programmable Quantum System Controller",
  "manufacturer": "Zurich Instruments",
  "description": "用于量子实验平台中的系统级时序与触发控制设备，可配置触发重复次数和触发间隔，并启动、停止及监测触发序列的执行进度。",
  "description_en": "A system-level timing and trigger control instrument for quantum experiments. It configures trigger repetitions and trigger intervals, and can start, stop, and monitor the progress of trigger sequence execution.",
  "tag_hints": [
    "quantum control",
    "trigger generation",
    "timing synchronization",
    "system controller",
    "Zurich Instruments PQSC",
    "sequencing"
  ],
  "actions": [
    {
      "action_name": "auto-check_errors",
      "description": "检查设备错误状态。",
      "description_en": "Check the device for errors."
    },
    {
      "action_name": "auto-clear_errors",
      "description": "清除设备错误记录。",
      "description_en": "Clear device errors."
    },
    {
      "action_name": "auto-clock_freq",
      "description": "读取控制器时钟频率。",
      "description_en": "Read the controller clock frequency."
    },
    {
      "action_name": "auto-set_holdoff",
      "description": "设置触发之间的时间间隔。",
      "description_en": "Set the interval between triggers."
    },
    {
      "action_name": "auto-set_repetitions",
      "description": "设置要生成的触发重复次数。",
      "description_en": "Set the number of trigger repetitions to generate."
    },
    {
      "action_name": "auto-start",
      "description": "启动执行单元并开始触发序列。",
      "description_en": "Start the execution unit and begin the trigger sequence."
    },
    {
      "action_name": "auto-stop",
      "description": "停止执行单元。",
      "description_en": "Stop the execution unit."
    },
    {
      "action_name": "auto-track_progress",
      "description": "显示触发生成进度。",
      "description_en": "Display the trigger generation progress."
    },
    {
      "action_name": "auto-get_progress",
      "description": "获取触发生成进度。",
      "description_en": "Get trigger generation progress."
    }
  ]
}

